import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { parse as parseToml } from "smol-toml";
import { z } from "zod";

// Generated by the host's existing SDK export. Used only by catalog build tools.
import { AiProviderCatalogDocumentSchema, type AiProviderCatalogDocument } from "../packages/host-stubs/types/packages/sdk/core/ai-model.js";

const ObjectSchema = z.record(z.string(), z.unknown());

/** TOML has no null: omitted nullable metadata encodes unknown, never a default. */
function nullableMetadata(input: unknown, keys: readonly string[]): Record<string, unknown> {
  const object = ObjectSchema.parse(input);
  for (const key of keys) if (!(key in object)) object[key] = null;
  return object;
}

function configuration(input: unknown): unknown {
  const value = ObjectSchema.parse(input);
  if (!Array.isArray(value.fields)) return value;
  return { ...value, fields: value.fields.map((input: unknown) => {
    const field = ObjectSchema.parse(input);
    if (field.kind === "secret") return nullableMetadata(field, ["description"]);
    if (field.kind === "setting") {
      const setting = nullableMetadata(field.field, ["description", "confirmationMessage"]);
      const type = ObjectSchema.parse(setting.fieldType);
      const fieldType = type.type === "string" ? nullableMetadata(type, ["maxLength"])
        : type.type === "number" ? nullableMetadata(type, ["min", "max"]) : type;
      return { ...field, field: { ...setting, fieldType } };
    }
    return field;
  }) };
}

/** Parse all definitions before producing any output; never execute provider data. */
export function readProviderCatalog(providersDirectory: string): AiProviderCatalogDocument {
  const entries = readdirSync(providersDirectory).filter((name) => name.endsWith(".toml")).sort().map((name) => {
    const { models, ...input } = ObjectSchema.parse(parseToml(readFileSync(join(providersDirectory, name), "utf8")));
    const provider = { ...nullableMetadata(input, ["endpoint"]), configuration: configuration(input.configuration) };
    const normalizedModels = models === undefined ? [] : Array.isArray(models) ? models.map((model: unknown) => {
      const value = nullableMetadata(model, ["providerConnectionId", "contextTokens", "languageCapabilities", "dimensions", "normalization", "artifactDigest", "price"]);
      return { ...value, price: value.price === null ? null : nullableMetadata(value.price, ["cacheReadPerMtokMicros", "cacheWritePerMtokMicros", "cacheWriteOneHourPerMtokMicros", "reasoningPerMtokMicros"]) };
    }) : models;
    return { provider, models: normalizedModels };
  });
  const document = AiProviderCatalogDocumentSchema.parse({ schemaVersion: 1, entries });
  return { ...document, entries: [...document.entries].sort((a, b) => a.provider.id < b.provider.id ? -1 : a.provider.id > b.provider.id ? 1 : 0) };
}

export function buildProviderCatalog(providersDirectory: string, output: string): AiProviderCatalogDocument {
  const document = readProviderCatalog(providersDirectory);
  mkdirSync(dirname(output), { recursive: true });
  writeFileSync(output, JSON.stringify(document, null, 2) + "\n");
  return document;
}

if (import.meta.main) buildProviderCatalog(join(import.meta.dir, "..", "providers"), join(import.meta.dir, "..", "plugins_dist", "providers.json"));
